input.script:
() => {
  const ingredients = [];
  document.querySelectorAll('.mntl-structured-ingredients__list-item').forEach(el => ingredients.push(el.textContent.trim().replace(/\s+/g,' ')));
  const title = document.querySelector('h1')?.textContent?.trim();
  const rating = document.querySelector('#mm-recipes-review-bar__rating_1-0')?.textContent?.trim();
  const reviews = document.querySelector('#mm-recipes-review-bar__comment-count_1-0')?.textContent?.trim();
  return {title, rating, reviews, ingredients};
}

() => {
  const result = {};
  result.title = document.querySelector('h1')?.textContent?.trim();
  result.rating = document.querySelector('#mm-recipes-review-bar__rating_1-0')?.textContent?.trim();
  result.reviews = document.querySelector('#mm-recipes-review-bar__comment-count_1-0')?.textContent?.trim();
  result.ingredientsItems = document.querySelectorAll('[data-ingredient-name="true"]').length;
  const allText = document.body.innerText;
  const idx = allText.indexOf('Ingredients');
  result.ingredientsSnippet = idx >= 0 ? allText.substring(idx, idx+2000) : 'not found';
  return result;
}
